import { createStorage } from 'unstorage'
import capacitorPreferences from 'unstorage/drivers/capacitor-preferences'
import type { AppSettings, MatchCondition, ScanResult, ScanRule, ScanProfile, RuleEvalResult } from '~/types/scanner'

const SETTINGS_KEY = 'scanEngine'

// --------------------------------------------------------//
// TBA: This is an idea generated by AI and is NOT IN USE  //
// --------------------------------------------------------//
const defaultSettings = (): AppSettings => ({
  activeProfileId: '',
  profiles: [],
  preferences: {
    hapticFeedback: true,
    beepOnScan: true,
    torchEnabled: false,
    scanDelay: 500,
    cameraFacing: 'back',
  },
})

// ─── Condition Evaluator ──────────────────────────────────────────────────────

function evaluateCondition(condition: MatchCondition, scan: ScanResult): boolean {
  const raw = condition.field === 'text' ? scan.text : scan.format
  const a = condition.caseSensitive ? raw : raw.toLowerCase()
  const b = condition.caseSensitive ? condition.value : condition.value.toLowerCase()

  switch (condition.operator) {
    case 'startsWith': return a.startsWith(b)
    case 'endsWith': return a.endsWith(b)
    case 'contains': return a.includes(b)
    case 'equals': return a === b
    case 'regex': return new RegExp(condition.value, condition.caseSensitive ? '' : 'i').test(raw)
  }
}

function evaluateRule(rule: ScanRule, scan: ScanResult): boolean {
  if (!rule.enabled || rule.conditions.length === 0) return false

  return rule.conditionLogic === 'AND'
    ? rule.conditions.every(c => evaluateCondition(c, scan))
    : rule.conditions.some(c => evaluateCondition(c, scan))
}

// ─── Composable ───────────────────────────────────────────────────────────────

export const useScanEngine = () => {
  const kv = createStorage({
    driver: capacitorPreferences({ base: 'scanSettings' }),
  })

  const settings = reactive<AppSettings>(defaultSettings())

  // ─── Persistence ────────────────────────────────────────────────────────────

  const load = async (): Promise<void> => {
    const stored = await kv.getItem<AppSettings>(SETTINGS_KEY)
    if (stored) Object.assign(settings, stored)
  }

  const save = async (): Promise<void> => {
    await kv.setItem(SETTINGS_KEY, JSON.parse(JSON.stringify(settings)))
  }

  const reset = async (): Promise<void> => {
    Object.assign(settings, defaultSettings())
    await save()
  }

  // ─── Profile Management ─────────────────────────────────────────────────────

  const activeProfile = computed<ScanProfile | undefined>(() =>
    settings.profiles.find(p => p.id === settings.activeProfileId),
  )

  const addProfile = async (label: string): Promise<ScanProfile> => {
    const profile: ScanProfile = {
      id: crypto.randomUUID(),
      label,
      rules: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }
    settings.profiles.push(profile)
    if (!settings.activeProfileId) settings.activeProfileId = profile.id
    await save()
    return profile
  }

  const removeProfile = async (profileId: string): Promise<void> => {
    const idx = settings.profiles.findIndex(p => p.id === profileId)
    if (idx === -1) return
    settings.profiles.splice(idx, 1)
    if (settings.activeProfileId === profileId) {
      settings.activeProfileId = settings.profiles[0]?.id ?? ''
    }
    await save()
  }

  const setActiveProfile = async (profileId: string): Promise<void> => {
    if (!settings.profiles.find(p => p.id === profileId)) {
      throw new Error(`Profile ${profileId} not found`)
    }
    settings.activeProfileId = profileId
    await save()
  }

  // ─── Rule Management ────────────────────────────────────────────────────────

  const getRules = (profileId = settings.activeProfileId): ScanRule[] =>
    settings.profiles.find(p => p.id === profileId)?.rules ?? []

  const addRule = async (rule: Omit<ScanRule, 'id'>, profileId = settings.activeProfileId): Promise<ScanRule> => {
    const profile = settings.profiles.find(p => p.id === profileId)
    if (!profile) throw new Error(`Profile ${profileId} not found`)

    const newRule: ScanRule = { id: crypto.randomUUID(), ...rule }
    profile.rules.push(newRule)
    profile.updatedAt = Date.now()
    await save()
    return newRule
  }

  const updateRule = async (ruleId: string, patch: Partial<Omit<ScanRule, 'id'>>, profileId = settings.activeProfileId): Promise<void> => {
    const profile = settings.profiles.find(p => p.id === profileId)
    if (!profile) throw new Error(`Profile ${profileId} not found`)

    const rule = profile.rules.find(r => r.id === ruleId)
    if (!rule) throw new Error(`Rule ${ruleId} not found`)

    Object.assign(rule, patch)
    profile.updatedAt = Date.now()
    await save()
  }

  const removeRule = async (ruleId: string, profileId = settings.activeProfileId): Promise<void> => {
    const profile = settings.profiles.find(p => p.id === profileId)
    if (!profile) return

    const idx = profile.rules.findIndex(r => r.id === ruleId)
    if (idx !== -1) {
      profile.rules.splice(idx, 1)
      profile.updatedAt = Date.now()
      await save()
    }
  }

  const reorderRules = async (orderedIds: string[], profileId = settings.activeProfileId): Promise<void> => {
    const profile = settings.profiles.find(p => p.id === profileId)
    if (!profile) return

    profile.rules.sort((a, b) => orderedIds.indexOf(a.id) - orderedIds.indexOf(b.id))
    profile.updatedAt = Date.now()
    await save()
  }

  // ─── Scan Evaluation ────────────────────────────────────────────────────────

  /**
   * Attempt a scan result against the active profile's rules.
   * Returns all evaluation results; respects stopPropagation.
   */
  const attemptScan = (scan: ScanResult, profileId = settings.activeProfileId): RuleEvalResult[] => {
    const profile = settings.profiles.find(p => p.id === profileId)
    if (!profile) return []

    const results: RuleEvalResult[] = []

    for (const rule of profile.rules) {
      const matched = evaluateRule(rule, scan)
      results.push({
        rule,
        matched,
        action: matched ? rule.action : null,
      })
      if (matched && rule.stopPropagation) break
    }

    return results
  }

  /** Convenience: only returns rules that matched, with their actions. */
  const getMatchedActions = (scan: ScanResult, profileId = settings.activeProfileId): RuleEvalResult[] =>
    attemptScan(scan, profileId).filter(r => r.matched)

  // ─── Preferences ────────────────────────────────────────────────────────────

  const updatePreferences = async (patch: Partial<AppSettings['preferences']>): Promise<void> => {
    Object.assign(settings.preferences, patch)
    await save()
  }

  return {
    // state
    settings,
    activeProfile,

    // persistence
    load,
    save,
    reset,

    // profiles
    addProfile,
    removeProfile,
    setActiveProfile,

    // rules
    getRules,
    addRule,
    updateRule,
    removeRule,
    reorderRules,

    // scanning
    attemptScan,
    getMatchedActions,

    // preferences
    updatePreferences,
  }
}
